import Producto from './producto.js';

export default class Accesorios extends Producto {
    #tipoMascota;
    #talla;
    #color;

    constructor(n, p, d, i, tipoMascota, talla, color) {
        super(n, p, d, i, 'Accesorios');

        this.#tipoMascota = tipoMascota;
        this.#talla = talla;
        this.#color = color;
    }

    get tipoMascota() {
        return this.#tipoMascota; 
    }

    set tipoMascota(v) { 
        this.#tipoMascota = v; 
    }

    get talla() { 
        return this.#talla; 
    }

    set talla(v) { 
        this.#talla = v; 
    }

    get color() { 
        return this.#color; 
    }

    set color(v) { 
        this.#color = v; 
    }
}
